<script lang="ts">import {colors} from '../charts';let {values}:{values:(number|null)[]}=$props();</script>
<div class="trend" role="img" aria-label="Readiness over the last 30 days; missing days are gaps">{#each values as value,i}<div class="day">{#if value!=null}<i style:height={Math.max(3,Math.min(100,value))+'%'} style:background={value<50?colors.coral:value<70?colors.amber:colors.mint} class:last={i===values.length-1}></i>{/if}</div>{/each}</div><div class="axis"><span>30 days ago</span><span>Today</span></div>
<style>.trend{height:108px;display:flex;align-items:flex-end;gap:3px;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.08)}.day{height:100%;flex:1;display:flex;align-items:flex-end;min-width:0}.day i{display:block;width:100%;border-radius:4px 4px 1px 1px;opacity:.55}.day i.last{opacity:1}.axis{display:flex;justify-content:space-between;font:500 11px Inter;color:var(--text3);margin-top:8px}</style>
